create table public.match_results (user_id uuid not null references public.profiles(id) on delete cascade, match_id text not null check (char_length(match_id) between 6 and 64), played_at timestamptz not null default now(), won boolean not null, mode text not null check (mode in ('team','solo')), size integer not null check (size between 3 and 5), players integer not null check (players between 1 and 50), photos integer not null default 0 check (photos between 0 and 200), valid_photos integer not null default 0 check (valid_photos between 0 and 200), cells integer not null default 0 check (cells between 0 and 25), lines integer not null default 0 check (lines between 0 and 12), primary key (user_id, match_id));
alter table public.match_results enable row level security;
create or replace function public.record_match(p_match text, p_won boolean, p_mode text, p_size integer, p_players integer, p_photos integer, p_valid integer, p_cells integer, p_lines integer) returns void language plpgsql security definer set search_path = public as $$ declare me uuid := public.require_account(); begin if not exists (select 1 from profiles where id = me) then raise exception 'no_profile'; end if; if (select count(*) from match_results where user_id = me and played_at > now() - interval '2 minutes') >= 3 then raise exception 'too_fast'; end if; insert into match_results (user_id, match_id, won, mode, size, players, photos, valid_photos, cells, lines) values (me, p_match, coalesce(p_won, false), p_mode, p_size, least(greatest(p_players, 1), 50), least(greatest(p_photos, 0), 200), least(greatest(p_valid, 0), least(greatest(p_photos, 0), 200)), least(greatest(p_cells, 0), p_size * p_size), least(greatest(p_lines, 0), 2 * p_size + 2)) on conflict (user_id, match_id) do nothing; end; $$;
create or replace function public.get_profile(p_user uuid default null) returns json language plpgsql security definer set search_path = public as $$ declare me uuid := public.require_account(); target uuid := coalesce(p_user, me); r json; begin if target <> me and not exists (select 1 from friendships where status = 'accepted' and ((requester = me and addressee = target) or (requester = target and addressee = me))) then raise exception 'not_allowed'; end if; select json_build_object('id', p.id, 'name', p.name, 'friend_code', p.friend_code, 'since', p.created_at, 'is_me', p.id = me, 'stats', (select json_build_object('matches', count(*), 'wins', count(*) filter (where won), 'team_matches', count(*) filter (where mode = 'team'), 'team_wins', count(*) filter (where mode = 'team' and won), 'solo_matches', count(*) filter (where mode = 'solo'), 'solo_wins', count(*) filter (where mode = 'solo' and won), 'photos', coalesce(sum(photos), 0), 'valid_photos', coalesce(sum(valid_photos), 0), 'cells', coalesce(sum(cells), 0), 'lines', coalesce(sum(lines), 0)) from match_results where user_id = p.id), 'recent', (select coalesce(json_agg(x order by x.played_at desc), '[]'::json) from (select played_at, won, mode, size, players, photos, valid_photos, cells, lines from match_results where user_id = p.id order by played_at desc limit 10) x)) into r from profiles p where p.id = target; if r is null then raise exception 'no_profile'; end if; return r; end; $$;
revoke all on function public.record_match(text, boolean, text, integer, integer, integer, integer, integer, integer) from public;
revoke all on function public.get_profile(uuid) from public;
grant execute on function public.record_match(text, boolean, text, integer, integer, integer, integer, integer, integer) to authenticated;
grant execute on function public.get_profile(uuid) to authenticated;
